import { KERNEL } from '../../../../../../lib/NJSCore/CV/ConvolutionalFilter/PixelMapFilter';
import { ImageProcessor } from './ImageProcessor';
import { VideoProcessor } from './VideoProcessor';

export const getImageFromURL = async (src: string = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/bg/zoom-James-River-Kayaking.jpg') => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.src = src;
        img.crossOrigin = 'Anonymous';
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error('cannot loade the img by url...'));
    });
};

export class Implmentation {
    public hostDiv: HTMLElement;

    public imageProcessor: ImageProcessor;
    public videoProcessor: VideoProcessor;

    private num = 0;

    constructor(hostDiv: HTMLElement) {
        this.hostDiv = hostDiv;
    }
    public async init(ctx: CanvasRenderingContext2D) {

        const img = await getImageFromURL();
        const image = img as HTMLImageElement;

        this.imageProcessor = new ImageProcessor(this, image);
        this.videoProcessor = new VideoProcessor(this, this.hostDiv);
    }
    public toggle() {
        // console.log('dddd');
        this.num++;
    }
    public setFilter(k: KERNEL) {
        if (this.num % 2 === 0) {
            this.videoProcessor.setFilter(k);
        } else {
            this.imageProcessor.setFilter(k);
        }
    }
    public render(ctx: CanvasRenderingContext2D) {

        if (this.num % 2 === 0) {
            if (this.videoProcessor) {
                this.videoProcessor.render(ctx);
            }
        } else {
            if (this.imageProcessor) {
                this.imageProcessor.render(ctx);
            }
        }

    }
}